function saveState(){try{localStorage.setItem('mingalar-completed-v1',JSON.stringify([...completed]));localStorage.setItem('mingalar-readiness-v1',JSON.stringify(readiness));}catch{}}
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);});}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2600);}
function codeBlock(code,label='PowerShell'){const id=codes.push(code)-1;return `<div class="code-block"><div class="code-toolbar"><span><span class="code-dots"><i></i><i></i><i></i></span>${esc(label)}</span><button class="copy-button" data-copy="${id}" aria-label="${esc(label)} code ကူးယူမယ်">${icon('copy')}<span>Copy</span></button></div><pre><code>${esc(code)}</code></pre></div>`;}
function banner(text,tone=''){return `<div class="info-banner ${tone}">${icon('info')}<p>${text}</p></div>`;}
function pageIntro(id,title,description){const n=modules.findIndex(m=>m.id===id)+1;return `<div class="page-intro"><div><div class="eyebrow"><span class="line"></span>${esc(modules[n-1]?.en || 'Your learning toolkit')}</div><h1 class="page-title">${title}</h1><p class="page-desc">${description}</p></div><span class="chapter-count">${n>0?`LESSON ${String(n).padStart(2,'0')} / 08`:'TOOLKIT'}</span></div>`;}
function moduleFooter(){const index=modules.findIndex(m=>m.id===currentPage);if(index<0)return '';const done=completed.has(currentPage),next=modules[index+1];return `<div class="module-footer"><button class="completion-button ${done?'done':''}" id="mark-complete" aria-pressed="${done}">${icon(done?'check':'circle')}<span>${done?'လေ့လာပြီးပါပြီ':'ဒီသင်ခန်းစာ လေ့လာပြီးကြောင်း မှတ်မယ်'}</span></button>${next?`<a class="next-link" href="#${next.id}"><span>နောက်သင်ခန်းစာ<strong>${next.name}</strong></span>${icon('arrow')}</a>`:`<a class="next-link" href="#resources"><span>လက်တွေ့ဆက်လုပ်ဖို့<strong>Starter kit နဲ့ အရင်းအမြစ်များ</strong></span>${icon('arrow')}</a>`}</div>`;}
function renderNav(){document.getElementById('course-nav').innerHTML=modules.map((m,i)=>`<a class="nav-item ${currentPage===m.id?'active':''} ${completed.has(m.id)?'complete':''}" href="#${m.id}" ${currentPage===m.id?'aria-current="page"':''}><span class="nav-number">${completed.has(m.id)?icon('check'):String(i+1).padStart(2,'0')}</span><span class="nav-title">${m.name}</span>${currentPage===m.id?'<span class="nav-arrow">›</span>':''}</a>`).join('');document.getElementById('progress-label').textContent=`${completed.size} / 8`;document.getElementById('progress-bar').style.width=`${completed.size/8*100}%`;}
